    private readonly GraphicsDevice _device;private readonly SpriteBatch _batch;private readonly Texture2D _pixel;private bool _disposed;
    private bool _highContrast;private ColorVisionMode _colorVisionMode;private float _interfaceScale=1f;
    public Phase8HudRenderer(GraphicsDevice device){_device=device;_batch=new SpriteBatch(device);_pixel=new Texture2D(device,1,1);_pixel.SetData(new[]{Color.White});}
    public void Draw(PlayerPresentationSnapshot snapshot,InputDeviceKind device,bool diagnostics,Phase20UserSettings settings,CombatPresentationSnapshot? combat=null,Phase13OverlayModel? itemOverlay=null,QuestTrackerHudModel? questTracker=null,HudWorldFeedbackModel? worldFeedback=null,int interfaceFrame=0,UiInputDevice? promptInputDevice=null)
