    private void DrawItemOverlay(Phase13OverlayModel model,int w,int h){int panelWidth=Math.Max(240,Math.Min(900,Math.Max(240,w-40))),panelHeight=Math.Max(220,Math.Min(620,Math.Max(220,h-40))),left=Math.Max(0,(w-panelWidth)/2),top=Math.Max(0,(h-panelHeight)/2);DrawRect(new Rectangle(0,0,w,h),new Color(0,0,0,150));DrawRect(new Rectangle(left,top,panelWidth,panelHeight),new Color(10,22,22,245));DrawBorder(new Rectangle(left,top,panelWidth,panelHeight),new Color(126,201,171));DrawText(model.Title.ToUpperInvariant(),left+28,top+24,3,new Color(209,238,219));int maxLines=Math.Max(1,(panelHeight-150)/22);int selected=model.SelectedIndex<0?-1:Math.Clamp(model.SelectedIndex,0,Math.Max(0,model.Lines.Count-1));int first=selected<0?0:Math.Clamp(selected-maxLines/2,0,Math.Max(0,model.Lines.Count-maxLines));for(int i=0;i<Math.Min(maxLines,model.Lines.Count-first);i++){int index=first+i,y=top+76+i*22;if(index==selected)DrawRect(new Rectangle(left+18,y-4,panelWidth-36,20),new Color(51,87,75,220));string line=model.Lines[index];int maxChars=Math.Max(12,(panelWidth-70)/12);if(line.Length>maxChars)line=line[..Math.Max(1,maxChars-3)]+"...";DrawText((index==selected?"> ":"  ")+line.ToUpperInvariant(),left+28,y,2,index==selected?new Color(242,218,139):new Color(181,211,196));}DrawText(model.Status.ToUpperInvariant(),left+28,top+panelHeight-60,1,new Color(224,174,113));DrawText(model.Footer.ToUpperInvariant(),left+28,top+panelHeight-34,1,new Color(152,194,177));}
    private void DrawInteractionPrompt(InteractionPromptHudModel model,Rectangle area){if(area.Width<=0||area.Height<=0)return;DrawRect(area,new Color(8,20,19,224));DrawBorder(area,model.Enabled?new Color(120,202,168):new Color(220,157,102));int textScale=Math.Clamp((int)MathF.Round(_interfaceScale),1,2);string action=model.Enabled?$"[{model.BindingLabel}] {model.ActionLabel.ToUpperInvariant()}":model.ActionLabel.ToUpperInvariant();DrawTextCentered(TrimHud(action,Math.Max(12,(area.Width-24)/(6*textScale))),area.Center.X,area.Y+9,textScale,model.Enabled?new Color(222,240,228):new Color(239,183,119));DrawTextCentered(TrimHud(model.TargetName.ToUpperInvariant(),Math.Max(12,(area.Width-24)/6)),area.Center.X,area.Y+32,1,new Color(163,200,185));if(!string.IsNullOrWhiteSpace(model.SecondaryLine)&&area.Height>=66)DrawTextCentered(TrimHud(model.SecondaryLine!.ToUpperInvariant(),Math.Max(12,(area.Width-24)/6)),area.Center.X,area.Bottom-18,1,model.Enabled?new Color(157,193,181):new Color(239,183,119));}
    private void DrawQuestTracker(QuestTrackerHudModel model,Rectangle area){DrawRect(area,new Color(10,22,22,218));DrawBorder(area,new Color(105,180,151));int max=Math.Max(12,(area.Width-24)/6);DrawText("TRACKED: "+TrimHud(model.Title,Math.Max(8,max-9)),area.X+10,area.Y+9,1,new Color(222,201,139));DrawText(TrimHud(model.Objective,max),area.X+10,area.Y+31,1,new Color(207,235,218));if(!string.IsNullOrWhiteSpace(model.Distance))DrawText(TrimHud(model.Distance!,max),area.X+10,area.Y+52,1,new Color(157,193,181));}
    private void DrawToasts(HudWorldFeedbackModel feedback,Rectangle area,int interfaceFrame,bool reduceMotion){if(area.Width<=0||area.Height<=0)return;int y=area.Y;int gap=Math.Clamp((int)MathF.Round(7*_interfaceScale),5,12);int toastHeight=Math.Clamp((int)MathF.Round(66*_interfaceScale),56,104);foreach(HudToast toast in feedback.Toasts.TakeLast(5).Reverse()){int age=toast.AgeFrames(interfaceFrame);int remaining=Math.Max(0,toast.LifetimeFrames-age);float alpha=Math.Clamp(Math.Min(age/10f,remaining/22f),0f,1f);if(reduceMotion)alpha=remaining>0?1f:0f;int slide=reduceMotion?0:(int)MathF.Round((1f-Math.Clamp(age/12f,0f,1f))*Math.Min(48,area.Width/5));Rectangle bounds=new(area.X+slide,y,Math.Max(1,area.Width-slide),toastHeight);Color accent=ToastAccent(toast.Kind);DrawRect(bounds,WithAlpha(new Color(8,20,19,235),alpha));DrawBorder(bounds,WithAlpha(accent,alpha));DrawText(TrimHud(toast.Title.ToUpperInvariant(),Math.Max(10,(bounds.Width-24)/6)),bounds.X+10,bounds.Y+8,1,WithAlpha(accent,alpha));IReadOnlyList<string> lines=WrapHud(toast.Body,Math.Max(12,(bounds.Width-24)/6));int lineY=bounds.Y+29;foreach(string line in lines.Take(2)){DrawText(line.ToUpperInvariant(),bounds.X+10,lineY,1,WithAlpha(new Color(205,230,216),alpha));lineY+=18;}y+=toastHeight+gap;if(y+toastHeight>area.Bottom)break;}}
