    private void DrawText(string text,int x,int y,int scale,Color color){int cursor=x;foreach(char raw in text){char c=char.ToUpperInvariant(raw);if(c=='\n'){y+=8*scale;cursor=x;continue;}string[] glyph=Glyph(c);for(int row=0;row<7;row++)for(int col=0;col<5;col++)if(glyph[row][col]=='#')DrawRect(new Rectangle(cursor+col*scale,y+row*scale,scale,scale),color);cursor+=6*scale;}}
